def forward(
    self,
    x: torch.Tensor,
    physical_port_mask: torch.Tensor,
) -> dict[str, torch.Tensor]:
    if (
        x.ndim != 4
        or tuple(x.shape[1:]) != (16, 58, 32)
    ):
        raise ValueError(
            f"x shape={tuple(x.shape)}, "
            "expected [B,16,58,32]"
        )
    if (
        physical_port_mask.ndim != 3
        or tuple(
            physical_port_mask.shape[1:]
        ) != (16, 10)
        or physical_port_mask.shape[0] != x.shape[0]
    ):
        raise ValueError(
            "physical_port_mask must have shape "
            "[B,16,10]"
        )

    batch_size, num_nodes, num_features, time_steps = (
        x.shape
    )

    y = x.reshape(
        batch_size * num_nodes,
        num_features,
        time_steps,
    )
    y = F.relu(self.input_projection(y))
    for block in self.temporal_blocks:
        y = block(y)

    temporal_embedding = y[:, :, -1].reshape(
        batch_size,
        num_nodes,
        64,
    )

    node_input = torch.cat(
        (
            temporal_embedding,
            physical_port_mask.to(
                dtype=temporal_embedding.dtype
            ),
        ),
        dim=-1,
    )
    node_embedding = F.relu(
        self.node_projection(node_input)
    )

    source_logits = self.source_head(
        node_embedding
    ).squeeze(-1)
    transit_logits = self.transit_head(
        node_embedding
    ).squeeze(-1)
    victim_logits = self.victim_head(
        node_embedding
    ).squeeze(-1)
    path_logits = self.path_head(
        node_embedding
    ).squeeze(-1)

    pooled = torch.cat(
        (
            node_embedding.mean(dim=1),
            node_embedding.amax(dim=1),
        ),
        dim=-1,
    )
    graph_embedding = self.graph_projection(pooled)

    return {
        "attack_logits": self.attack_head(
            graph_embedding
        ).squeeze(-1),
        "count_logits": self.count_head(
            graph_embedding
        ),
        "source_logits": source_logits,
        "transit_logits": transit_logits,
        "victim_logits": victim_logits,
        "path_logits": path_logits,
    }

